"sc73w6": "이 브라우저가 볼 수 있는 버튼이 조종기에 없습니다",
"uo8hw2": "모든 스위치가 축으로 들어오고 있어 아직 확인을 누를 수 있는 것이 없습니다. 아무 스틱이나 가운데에서 벗어나게 1초쯤 잡고 있으면 한 번 누른 것으로 치니, 그걸로 여기 들어와 제대로 고칠 수 있습니다. 캘리브레이션 마지막에 확인으로 쓸 스위치를 움직이라고 묻고, 그 뒤로는 버튼처럼 작동합니다.",
