"1lzyy7t": "(가운데로 돌아오는 축). 휴대폰에서는 먼저 스틱 네 개가 모두 들어오는지 확인하세요. 안드로이드의 Chrome은 조종기 축을 네 개만 전달합니다. 스틱 도움말에서 볼 수 있습니다.",
"53c27k": "(가운데로 돌아오는 축). 캘리브레이션은 1분쯤 걸리고 완전히 해결됩니다.",
"1est9fl": "이 브라우저가 요 스틱을 보지 못합니다",
"1agkf6n": "요라고 추측한 축은 한 번도 움직이지 않았는데, 모르는 스틱 하나가 끝에서 끝까지 움직였습니다. 조종기가 추측과 다른 순서로 채널을 보내고 있고, 잃어버린 것이 요입니다. 캘리브레이션은 1분쯤 걸리며 어느 축이 무엇인지 이 페이지에 알려 줍니다.",
"x7203j": "이 브라우저가 스로틀을 요로 읽고 있습니다",
"1m52vjm": "스로틀로 읽는 축은 놓으면 가운데로 돌아오는데 스로틀은 절대 그러지 않습니다. 요로 읽는 축은 놓은 자리에 머무는데 그건 스로틀만 그렇습니다. 그래서 스로틀이 쿼드를 띄우지 않고 돌리고 있습니다. 캘리브레이션은 1분쯤 걸리며 어느 축이 무엇인지 이 페이지에 알려 줍니다.",
"5fqwjo": "이 브라우저가 조종기를 게임패드로 인식합니다",
"y5c806": "스틱 축 하나가 가운데에서 벗어난 채 머물러 있습니다. 게임패드 스틱은 절대 그러지 않고 조종기의 스로틀은 항상 그렇습니다. 게임패드로 읽으면 스틱이 엉뚱한 채널에 연결됩니다. 캘리브레이션은 1분쯤 걸리며 어느 축이 무엇인지 이 페이지에 알려 줍니다.",
"11e2cn1": "휴대폰에서 가장 흔한 원인은 Chrome이 조종기 축을 네 개만 전달하는 것입니다.",
"ehzk3y": "Low에서는 비행 중 타이머가 프레임을 그려야 하지만, 이 화면은 타이머가 그리는 속도 이상으로 새로 고쳐져 같은 프레임을 두 번 보여 주고 있었습니다. 페이지를 새로 고칠 때까지 디스플레이가 대신 속도를 맞춥니다. 타이머, 항상을 고르면 그래도 타이머를 유지합니다.",
"vl1tj": "비행 중에는 모든 프리셋에서 타이머가 프레임을 그립니다. 화면이 스틱에 더 빨리 반응하지만 GPU 부하, 발열, 배터리 소모가 늘고, 그동안 자동 그래픽은 멈춥니다. 리플레이와 필름은 디스플레이 박자를 유지합니다.",
"qi0jq2": "모든 프리셋에서 디스플레이가 프레임 속도를 맞춥니다. 브라우저의 기본 박자로, 배터리에 가장 부담이 적고 화면은 다음 새로 고침을 기다립니다.",
"1du9pl5": "Low에서는 비행 중 타이머가 프레임을 그려 화면이 스틱에 더 빨리 반응하지만 GPU 부하, 발열, 배터리 소모가 늘어납니다. 그동안 자동 그래픽은 멈추고, 리플레이와 필름은 디스플레이 박자를 유지합니다. Medium과 High에서는 디스플레이가 모든 속도를 맞춥니다.",
"91n7qr": "이 프리셋에서는 디스플레이가 프레임 속도를 맞춥니다. Low에서는 비행 중 타이머가 대신 그려 화면이 스틱에 더 빨리 반응하지만 GPU 부하, 발열, 배터리 소모가 늘어납니다.",
