"4rme3c": "라운드는 자동으로 이어집니다.",
"jrolc6": "친구와 빈자리, 그리고 빈자리를 채울 봇(쉬움, 보통, 어려움). 봇은 내 컴퓨터에서 비행하며 친구가 들어오면 자리를 내줍니다.",
