"1h2plxw": "첫 감염자가 탱크에서 기다리는 시간.",
"tdpjp": "누가 유리 탱크에서 매치를 시작하는지. 그 뒤로는 처음 잡힌 파일럿이 다음 라운드를 시작합니다.",
"cn1dzj": "방장이 각 매치를 시작합니다. 핑크 대 민트: 공을 상대 골대에 밀어 넣으세요.",
"1lk668x": "여기 있는 모두와 모든 봇을 핑크와 민트로 나눕니다. 비행 중 G를 눌러도 됩니다.",
