"1wrgk1g": "감염은 후프 전용이라 이 방의 모두가 후프로 비행합니다.",
"1bh88kh": "방의 모두가 같은 쿼드로 비행하며, 이 방은 {0}입니다. 내가 방장이므로 여기서 바꾸면 방의 모두가 함께 바뀝니다.",
