"brwzes": "바꾸려면 방을 나가세요.",
"14o38hk": "쿼드 선택",
"wc4nz9": "맵 1개에서 건너뜀",
"q6ou24": "맵 {0}개에서 건너뜀",
"iwujvz": "{0}에 항상 이걸로 비행을 체크했습니다. 누르면 모든 맵에서 다시 물어봅니다.",
"stn2d9": "스틱이 얼마나 멀리, 얼마나 날카롭게 움직이는지. 튠이 아니라 내 설정입니다. 아크로의 조종기는 이 곡선으로 비행하고, 키보드 레이스는 앵글로 시작합니다. 런 도중에 바꿔도 쿼드는 그 자리에 있고 시계는 계속 갑니다.",
"1m2xvti": "비행 모드",
"xjyq13": "아크로: 스틱은 회전 속도, 손을 떼면 자세를 유지합니다. 앵글: 스틱은 기울기(Betaflight의 60도 제한까지), 손을 떼면 수평으로 돌아옵니다. 이 레이스는 키보드로 비행하며, 키보드는 자체 선택이 있습니다(쿼드의 키보드 레이스). 이 줄은 그것을 바꿉니다. 비행 중 M으로도 전환됩니다.",
"1r5ubv6": "아크로: 스틱은 회전 속도, 손을 떼면 자세를 유지합니다. 앵글: 스틱은 기울기(Betaflight의 60도 제한까지), 손을 떼면 수평으로 돌아오고 요는 회전 속도 그대로입니다. 플립과 롤에는 아크로가 필요합니다. 비행 중 M으로도 전환되고 그대로 유지됩니다.",
"x7vih9": "한 팀의 인원, 봇의 실력, 끝나는 조건.",
"17g8v9b": "봇도 시계도 없이 혼자 계속 비행합니다.",
"11br69w": "봇과 그 촬영 실력.",
"m20i5w": "봇 없이 혼자 계속 촬영합니다.",
"c8vuhg": "대기실: 봇, 각 봇의 실력, 라운드, 먼저 출발하는 시간.",
"5typne": "봇 없이 혼자 학교를 비행합니다.",
"1afdza": "봇, 몰이 실력, 라운드가 끝나는 조건.",
"1t8ovw1": "봇도 시계도 없이 혼자 계속 몰이합니다.",
"1087r08": "봇, 실력, 리본 길이, 라운드.",
"1206cs3": "리본도 봇도 없이 계속 비행합니다.",
"899bgs": "봇, 실력, 라운드, 피해의 세기.",
"172ev2t": "총도 봇도 없이 계속 비행합니다.",
"1w5pf1h": "총과 미사일 버튼",
"14d24dx": "각각에 버튼이나 스위치를 고르고 테스트하세요.",
"d2okc9": "미니 게임으로 돌아가기",
"j88ayy": "계속",
"jsscfj": "느낌이 이상한가요?",
"1emvcwj": "스틱이 얼마나 멀리 가는지, 그리고 스로틀 제한. 여기서 바꿔도 쿼드는 그 자리에 있고 시계는 계속 갑니다.",
"17lkkrv": "그 밖에",
"1sc5qgc": "이름, 조종기, 그래픽, 사운드.",
"6gxuho": "{0}을(를) 끝냅니다.",
"wyh1np": "쿼드가 얼마나 무겁게 느껴지는지. 오른쪽은 더 무거워서 스로틀을 끊으면 떨어지고 점프 꼭대기에서 머물지 않습니다. 왼쪽은 더 가벼워 둥실 뜹니다. {0}이(가) 출고 상태의 쿼드입니다. 랩 도중에 바꾸면 그 랩은 무효가 되고, {1}이(가) 아닌 상태로 비행한 랩은 이름 옆에 무게를 달고 공개 보드에 올라갑니다.",
"1ayl725": "에어 그립",
"6bttpz": "공기가 쿼드를 얼마나 붙잡는지, 즉 스틱을 중립에 두었을 때 얼마나 미끄러져 가는지. 왼쪽은 계속 미끄러지며 더 빨라지고, 오른쪽은 공기가 붙잡아 더 빨리 멈추고 최고 속도도 낮아집니다. {0}이(가) 출고 상태의 쿼드이며, 파일럿들이 보낸 튠으로 정했습니다. 랩 도중에 바꾸면 그 랩은 무효가 되고, {1}이(가) 아닌 상태로 비행한 랩은 Tuned 태그가 붙어 공개 보드에 올라갑니다.",
"ior56v": "모터 파워",
"1x4irmq": "모터가 1볼트당 내는 속도, 즉 KV. 왼쪽은 부드럽게: 펀치가 순하고 최고 속도가 낮습니다. 오른쪽은 강하게: 그만큼 배터리 전압이 더 처지고, 호버 위치가 스틱에서 더 낮아집니다. {0}이(가) 출고 상태의 쿼드이며, 파일럿들이 보낸 튠으로 정했습니다. 랩 도중에 바꾸면 그 랩은 무효가 되고, {1}이(가) 아닌 상태로 비행한 랩은 Tuned 태그가 붙어 공개 보드에 올라갑니다.",
"1bsvonq": "기본은 꺼짐. 켜면 쿼드가 땅에 있는 동안 스틱 사이에 무게와 함께 {0}이(가) 나타나고, 내 슬라이더로 비행한 뒤에는 질문이 나옵니다: 스톡 쿼드보다 느낌이 좋았나요? 예라고 답하지 않으면 아무것도 보내지 않습니다. 끄면 슬라이더가 어떻든 쿼드는 출고 상태로 비행합니다. 랩 도중에 전환해 비행 중인 쿼드가 바뀌면 그 랩은 무효가 됩니다.",
"5xvgod": "튠한 비행 뒤에 묻기",
"1siorg1": "내 슬라이더로 비행한 뒤, 스톡보다 느낌이 좋았는지 묻습니다. 언제든 아니요라고 답할 수 있고, 예 없이는 아무것도 보내지 않습니다. 끄면 묻지 않으며 슬라이더는 그대로 작동합니다.",
"187fv0s": "쿼드가 어떻게 나는지 튠 작업에 알려 주세요. 한 단어면 충분합니다. 내 튠, PID 조정, 레이트가 함께 전송됩니다.",
"16us7mj": "언어",
"2nnvct": "메뉴의 언어. 적용하려면 게임이 다시 시작됩니다.",
"1hmyggy": "이 컴퓨터에서 {0}을(를) 시도했지만 화면이 제때 그려지지 않아, 자동은 {1} 이하로 유지됩니다.",
"s4dnb5": "자동: {0}{1}(으)로 그리는 중. 프레임이 실제로 도착하는 모습을 보고, 화면이 늦으면 해상도를 낮추고, 런 사이에 프리셋을 바꿉니다.{2} 직접 고정하려면 프리셋을 고르세요.",
"1ejndm0": "그래픽",
"dcm8ea": "각 프레임을 페이지 뒤에 줄 세우지 않고 화면에 바로 그립니다. 스틱에서 화면까지의 시간이 한두 프레임 줄어들 수 있습니다. 화면이 찢어져 보일 수 있습니다.",
"1ttxrpl": "다음 로드부터 꺼짐. {0} 이 브라우저는 새로 고칠 때까지 계속 사용합니다.",
"1j0ql37": "꺼짐. {0} 켠 뒤 새로 고치세요.",
