"gtjdfs": "저지연 보기 사용 중",
"1ampkwb": "이 모니터가 60 Hz보다 빠르게 동작할 수 있다면, 시스템이 최고 주사율로 설정되어 있는지 확인하세요(Windows: 설정, 디스플레이, 고급 디스플레이). 페이지는 주어진 디스플레이의 속도까지만 그릴 수 있습니다.",
