"jgkrww": "조종기를 조이스틱 모드로 연결하세요. 여러 개가 연결되어 있다면 여기서 어느 것으로 비행할지 고릅니다.",
"1y6zyev": "기기 하나가 연결되어 있습니다: {0}. 열어서 확인하거나 키보드로 전환하세요.",
"1a5n4iv": "기기 {0}개가 연결되어 있습니다. 쓰고 싶은 기기를 움직이세요. Windows는 게임 컨트롤러 순서로 나열하며, 이 화면에서 고릅니다.",
"hkrgl0": "야외 필드의 게이트 트랙에서 시간과 겨룹니다. 크고 빠른 레이싱 쿼드로, 완주한 랩은 모두 공개 보드에 올릴 수 있습니다.",
"1rnl54t": "같은 타임 어택을 실내에서. 거실에 들어가는 트랙을 작은 덕트형 후프로 달립니다.",
"1kaa7l9": "모든 프리스타일 맵: 마을, Nick Burns, Heads, Joshua Bardwell의 집, Thomas More's Shop, Sunnyfield, Shiokaze Point, Hibari Yard, 그리고 파일럿들이 만들어 보드에 공개한 모든 맵. 시계도 게이트도 없고, 트릭 이름은 안에서 켜고 끌 수 있습니다.",
