"19ybx9k": "직접 만들어 보세요. 5인치용 레이스 트랙, 후프용 방, 또는 폐건물과 크레인, 이름 붙은 갭이 있는 프리스타일 맵을 위에서 그리고 같은 페이지에서 바로 비행합니다.",
"1rjxeiy": "첫 호버부터 프로 라이선스까지. 비행을 배우고, 루키 라이선스를 따고, 스킬 트리에서 레이스나 프리스타일을 올려 보세요. 한 번도 날려 본 적이 없다면 여기서 시작하세요.",
