"10nopfd": "시야각",
"unl4q1": "넓을수록 더 많이 보이고, 좁을수록 확대됩니다. 좁게는 FPV 렌즈가 화면 가운데에 주는 느낌과 같고, 표준은 폭을 조금 되돌려 주며, 가장 넓게는 이 화면이 정직하게 낼 수 있는 최대라서 게이트가 더 작게 보입니다.",
"4emmbg": "어안",
"1u80da4": "실제 FPV 렌즈처럼 화면을 휘게 합니다. 모서리는 시야각이 정한 자리에 있고, 가장자리는 안으로 눌리고, 가운데가 커집니다. 끄면 휘지 않은 곧은 화면입니다. 넓은 시야에서 멀미가 나면 약하게나 중간을 써 보고, 시야각을 넓혀 폭을 되찾으세요.",
"1ir4yll": "카메라 각도",
"6gsnw2": "카메라가 기체에서 위로 얼마나 기울어 있는지. {0}은(는) 수평으로, 기수 방향을 봅니다. {1}은(는) 흔한 크루즈. 45에서 {2}은(는) 레이스. 약 30을 넘으면 요가 수평선을 기울이기 시작합니다. {3}도에서는 요의 {4}퍼센트가 화면에서 롤로 나타납니다. 실제로 기울어진 카메라가 그렇습니다. 줄이려면 레이트 화면에서 요 최대 레이트를 낮추세요.",
"1vp9w8f": "요가 수평선을 기울입니다",
"1hjxoj1": "틸트 {0}도에서는 요의 {1}퍼센트가 화면에서 롤로 나타납니다. 요 레이트 {3} deg/s에서 {2} deg/s만큼입니다. 실제로 기울어진 카메라가 그렇고, 보통의 해법은 요를 느리게 하는 것입니다. 요 최대 레이트를 {4}(으)로 낮추면 {5} deg/s로 돌아옵니다. 레이트 화면에서 언제든 바꿀 수 있습니다.",
"1f9wwkb": "이 신고를 남겨 둘까요?",
"v5eaek": "아직 보내지 않은 글이 있습니다. 여기서는 초안이 저장되지 않으므로 지금 닫으면 사라집니다.",
