"u3znvf": "{0}을(를) 지웁니다. 이 브라우저에만 있는 사본이라 되돌릴 수 없습니다. 숫자는 쿼드에 남고, 저장된 프로필만 사라집니다.",
"17l6uak": "먼저 프리셋을 불러오세요. 이 기능은 아래 줄들이 쓰고 있는 프로필을 삭제하는데, 지금은 저장된 프로필을 쓰고 있지 않습니다.",
"p52kwi": "기본값으로 되돌리기",
"17l8bg0": "기본 레이트로 돌아갑니다: Actual, 센터 {0} deg/s, 모든 축 끝에서 {1} deg/s, 엑스포 없음, 스로틀 제한 없음. 갓 플래시한 Betaflight의 70과 670보다 한 단계 아래이며, 각각 한 줄 차이입니다.",
"8av510": "이미 기본값입니다.",
"hu0m9h": "{0}은(는) 슬라이더를 RP 모드로 돌리므로, Configurator와 똑같이 롤과 피치에 적용되고 요는 스톡 값으로 남습니다.",
"x624ug": "{0}의 기본값은 {1}입니다. 그 값으로 되돌리면 변경이 사라집니다.",
"18oympv": "튠을 가져와 적용하는 중입니다. 모듈이 다시 읽는 순간 슬라이더가 나타납니다.",
"1grap3n": "PID 직접 설정",
"c5voz3": "켜짐. 슬라이더는 꺼져 있고(Configurator의 전문가 모드처럼 simplified_pids_mode OFF) 아래 표의 값으로 비행합니다. 끄면 슬라이더가 돌아오고 표는 기억됩니다.",
"15ryevg": "꺼짐. 아래 슬라이더가 펌웨어 자체의 간편 튜닝으로 PID를 움직입니다. 켜면 지금 비행 중인 값 그대로에서 시작해 모든 값을 직접 입력할 수 있습니다.",
"cv7xcu": "Betaflight의 튜닝 슬라이더",
"qfjx36": "펌웨어 벤치: PID뿐 아니라 필터, 기능, 모든 펌웨어 항목. Configurator 모양입니다. CLI 붙여넣기는 없습니다.",
"3owtby": "튠의 원래 값으로 돌아가기",
"idb6of": "{0}의 모든 슬라이더와 직접 설정한 PID를 지우고 튠의 기본 상태로 비행합니다. 다른 튠의 조정은 그대로 남습니다.",
"1jhnqh8": "{0}은(는) 이미 원래 값으로 비행 중입니다.",
"dfkhrn": "{0} 불러오는 중.",
"x90o0f": "{0}, PID 직접 설정. 모듈에서 다시 읽은 값입니다.",
"1lxpdkl": "내 슬라이더를 거친 {0}. 모듈에서 다시 읽은 값이며, 노치는 4.5.1 스톡입니다.",
"60528h": "{0}, 기본 그대로. 모듈에서 다시 읽은 값이며, 노치는 4.5.1 스톡입니다.",
"boibkp": "저장 안 됨",
"1q384zq": "3D 모드를 켤까요?",
"1bhsb37": "3D 비행 전용입니다. 모터가 양방향으로 돕니다. 스로틀 가운데가 추력 0이고 맨 아래는 뒤로 날아가므로, 설정, 파일럿, 3D 모드에서 다시 끌 때까지 일반 비행은 고장 난 것처럼 느껴집니다.",
"v65w1o": "꺼 두기",
"u2bdti": "3D 켜기",
"7g0dlj": "3D에서는 스로틀 가운데가 추력 0이고 맨 아래는 뒤로 날아가므로 일반 비행이 고장 난 것처럼 느껴집니다. 실수로 켜기 쉬웠습니다. 3D로 비행할 때만 켜 두세요.",
"mxrvnc": "3D 끄기",
"1s8d24o": "3D 켜 두기",
"avqznd": "이렇게 비행한 랩은 Tuned 태그가 붙어 공개 보드에 올라갑니다.",
"ohro0a": "현실 물리",
"s62yi0": "{0}에서 켜짐, 실험적: 실제 중력에서 실제 무게로 비행합니다. 더 자유롭게 돌고, 야외처럼 공기가 프롭을 밀어내며, 하강 기류는 남긴 자리에 머물고, 낮은 호버에서는 지면 효과가 받쳐 주고, 펀치하면 배터리 전압이 처지고, 프리스타일에서는 리셋할 때까지 닳아 갑니다. 회전, 모터, 배터리는 실제 쿼드 두 대의 비행 로그에 맞췄고, 나머지는 측정이 아니라 계산한 것입니다. 현실 물리 랩은 베스트 랩이 따로 기록됩니다.{1} 끄면 {2}이(가) 여기서 늘 날던 방식으로 비행합니다. 랩 도중에 바꾸면 그 랩은 무효가 됩니다.",
"bugmc9": "{0}에서 꺼짐: 여기서 늘 날던 방식 그대로. 켜면 실험적인 현실 모델이 됩니다: 실제 무게와 중력, 더 자유로운 회전, 더 사실적인 프롭 주변 공기, 남긴 자리에 머무는 하강 기류, 지면 효과, 그리고 전압이 처지고 프리스타일에서 닳아 가는 배터리.{1} 쿼드마다 설정이 따로 저장됩니다.",
"qzitkf": "현실 물리가 켜져 있습니다",
"11c30rz": "5인치가 이제 실제 쿼드의 비행 로그에 맞춘 실험적인 현실 모델로 비행합니다. 실제 쿼드만큼 무거워서 호버가 스로틀의 더 낮은 곳에 있고 속도를 잘 유지합니다. 더 자유롭게 돌고, 모터가 반응하는 데 잠깐 걸리며, 펀치하면 배터리 전압이 처집니다. 프리스타일에서는 배터리도 닳아 가고, 리셋하면 새 배터리가 됩니다. 예전 베스트 랩은 그대로 있고 예전 느낌으로 돌아가면 다시 나옵니다. 언제든 바꾸려면: 설정, 파일럿, 현실 물리.",
