"4uqxss": "땅에서 뒤집히면 TURTLE MODE 안내가 나타납니다. 오른쪽 패드에서 피치나 롤을 주면 뒤집힙니다. 타이밍을 맞출 필요는 없습니다. 손을 뗀 뒤 이륙하세요.",
