"1a3en5u": "이 페이지를 불러오기 전에 조종기를 조이스틱 모드로 두고, 설정에서 스틱 보정을 실행하세요.",
"8pq8oh": "피치로 커서를 옮기고, 오른쪽 롤로 선택, 왼쪽 롤로 뒤로 갑니다. 일시정지나 완주 뒤에는 스틱을 놓고 잠깐 기다린 다음 롤을 한 박자 유지하세요.",
"d45qj0": "다시 시작",
"ezjsbi": "키보드의 R, 또는 조종기의 스위치: 설정, 재시작 스위치에서 스위치를 젖히세요.",
"o7cl2g": "손을 떼면 그때의 자세를 유지합니다. 모든 선회는 직접 되돌려 날아야 합니다.",
"etorb5": "땅에서 뒤집히면 TURTLE MODE 안내가 나타납니다. 오른쪽 스틱으로 피치나 롤을 주면 뒤집힙니다. 타이밍을 맞출 필요는 없습니다. 스틱을 가운데로 두고 이륙하세요.",
