"14cfpm3": "각도 맞추기",
"11n5q78": "스로틀은 아이들. OSD가 30에서 40도쯤을 가리킬 때까지 앞으로 피치를 주세요. 스틱을 가운데로. 모터가 그 각도를 유지합니다.",
"1aa3oyb": "스로틀을 약 20퍼센트 넘게 펀치하세요. 유지가 풀리고 프롭이 공기를 물면서 날아갑니다. 출발 뒤 L을 다시 누르면 초기화됩니다.",
"14arqvb": "위쪽 화살표가 앞 피치. W가 스로틀. 론치 컨트롤은 유지하는 동안 아크로로 바꾸고, 출발하면 내 모드로 돌아옵니다.",
"r89zwp": "실제 보드와 같은 순서입니다. L이 모드 스위치입니다. launch_angle_limit와 launch_trigger_throttle_percent는 쿼드 아래 펌웨어 벤치에서 세밀하게 조정하세요.",
"1wrrqt3": "출발대에서 넘어지면 TURTLE MODE가 맡습니다. 피치나 롤로 뒤집으세요. 타이밍을 맞출 필요는 없습니다. 스틱을 가운데로 두고 L을 눌러 다시 출발하세요.",
"1x7j2uc": "론치 컨트롤, 쿼드에서 켰다면. 기울이고, 가운데, 펀치.",
"1xmpyfk": "비행 중 앵글과 아크로를 바꾸고 그 선택을 유지합니다.",
"1eyul69": "R, 그다음 Escape",
"1ns2uml": "출발선으로 돌아가 일시정지.",
"1hg0wdz": "땅에서 뒤집히면 TURTLE MODE 안내가 나타납니다. 화살표 키로 피치나 롤을 주면 뒤집힙니다. 타이밍을 맞출 필요는 없습니다. 손을 뗀 뒤 이륙하세요.",
"19jaz7h": "버그를 신고하거나 의견을 보냅니다. 공중에 있으면 일시정지한 뒤 양식을 엽니다.",
"1ogqofk": "패드는 비행 중에 엄지 아래에 나타납니다.",
"1harh8g": "스틱을 움직여 보세요. 조종기를 따라 움직입니다.",
"149s8uu": "L로 준비. 기울이고, 가운데, 펀치. 짐벌은 계속 손을 따라 움직입니다.",
"rt9bay": "키를 눌러 보세요. 손을 따라 움직입니다.",
"utog3i": "엄지 스틱은 진짜 비례 스틱이라 쿼드에서 정한 비행 모드로 비행합니다. 기본은 조종기처럼 아크로입니다. 배우는 동안에는 앵글이 더 순합니다. 오른쪽 패드를 놓으면 쿼드가 스스로 수평을 잡습니다.",
"1uqyqut": "조종기는 기본으로 아크로로 비행합니다. 스틱은 회전 속도를 요구하고, 놓으면 회전 없음을 요구해 쿼드가 그때의 자세를 유지합니다. 쿼드의 비행 모드에서, 또는 비행 중 M으로 바꾸세요.",
"wtsp1v": "기본은 꺼짐입니다. 유지 상태에서의 펀치는 격렬해서 모두가 원하지는 않기 때문입니다. 쿼드에서 켠 다음 패드 위에서 L. 초록색 LAUNCH 표시가 피치 각도입니다. 스로틀이 발사에 가까워지면 깜빡입니다.",
"t0ww0i": "키는 켜짐 아니면 꺼짐이라, 누르는 시간이 아날로그 역할을 합니다. 톡 치면 스틱이 조금 움직이고, 누르고 있으면 비행하기 좋은 양에 머물며, 길게 누르면 끝까지 갑니다. 키 레이스는 앵글로 시작하므로 놓으면 쿼드가 수평을 잡습니다.",
"arpbtx": "무엇을 비행할까",
"1k22ek3": "게이트 없음, 랩 없음, 2분",
