"r92sb6": "클린 랩이 하나라서 이것이 그 구성입니다. 한 번 더 비행하면 어디서 시간을 잃었는지 띠에 나타납니다.",
"2ba7i5": "시간을 가장 많이 잃은 곳은 {0}, 거기서의 내 최고보다 {1}.",
"m2w5l7": "모든 게이트의 내 최고를 합치면 {0}입니다.",
