"b21txc": "{0} 추격, {1}초 빠름",
"1y2w48a": "보드에 있는 {0}의 {1}, 내 {2}보다 빠른 랩 중 가장 가까운 기록이 고스트로 옆에서 비행합니다. 바로 출발 블록으로.",
"ocljwq": "보드에 기록된 모든 랩보다 빠릅니다. {0}의 {1}이(가) 기록의 고스트이며, 옆에서 나는 그 앞을 지키세요.",
"dj5y8q": "런 종료",
