"146lnlx": "{0}{1}은(는) 공개 보드에 있습니다. 내 이름으로 기록을 등록하면 거기에 나옵니다.",
"z120pj": "{0}은(는) 내 사본입니다{1}. 새 이름으로 공개하면 보드에 올라갑니다.",
"1fxf08k": "{0}은(는) 이 브라우저에 있습니다. 공개해 보드에 올리면 기록을 등록할 수 있습니다.",
"dru7ck": "{0}의 레이아웃은 아직 보드에 없습니다. 기록을 등록하기 전에 트랙을 업데이트하세요.",
