"1wsdw3g": "스티커",
"1de3yfm": "이 맵의 최고",
"1k5dzyz": "클린 런",
"kkya0r": "인식기가 이름 붙일 만한 것이 없었습니다. 트릭은 한 축을 중심으로 한 바퀴를 온전히 돌거나 무언가를 한 바퀴 도는 것입니다: 플립, 롤, 요 360, 레일 아래의 Powerloop. 모퉁이를 도는 것은 트릭이 아니며 일부러 0점입니다.",
"1y2kek1": "2분 동안 인식기가 이름 붙일 만한 것이 없었습니다. 트릭은 한 축을 중심으로 한 바퀴를 온전히 돌거나 무언가를 한 바퀴 도는 것입니다: 플립, 롤, 요 360, 레일 아래의 Powerloop. 모퉁이를 도는 것은 트릭이 아니며 일부러 0점입니다.",
"m2e6mk": "트릭 종류 하나 더",
"1rjo3vh": "이 런 등록은 트릭 점수 {0}을(를) 보드에 보냅니다. 보드는 아직 트릭만 알기 때문에 {1}의 갭, 아슬아슬한 통과, 추격은 여기서만 집계되고 거기에는 없습니다.",
"1lipfcv": "보드는 트릭만 받는데 이번 런에는 이름 붙은 트릭이 없어서 등록할 것이 없습니다. {0}의 갭, 아슬아슬한 통과, 추격은 여기서 집계됩니다.",
"nbri8l": "카메라 각도 {0}°",
"1xqk8yk": "{0}: {1} {2}, 비행하기에는 너무 적습니다.",
"182lfsh": "조종기나 게임패드가 없습니다.",
"1w5xlhk": "{0}에 쓸 스틱 고르기: 누른 다음 원하는 스틱을 미세요.",
"bwl76q": "조이스틱 한 대 연결됨",
"1chzf7k": "조이스틱 없음",
"exl51q": "이 페이지에서 비행할 수 있는 조이스틱이 없습니다.",
"18qtwr8": "그려진 스틱은 저장된 보정을 따릅니다.",
"pjwruo": "그려진 스틱은 이 페이지가 지금 읽는 방식이며, 보정하기 전까지는 추측입니다. 손을 따라오지 않더라도 그대로 고르고 {0}에서 스틱 보정을 실행하세요.",
"utpvx5": "이것을 쓸까요?",
"1kepfr": "움직이는 중",
"1feqd8h": "멈춤",
"10v17ee": "스틱 경로",
"p9ydk8": "엄지 스틱",
"1lrz4zo": "유리 위의 엄지는 짐벌 이동 거리의 4분의 1쯤밖에 안 되고 가운데로 되돌리는 힘도 없어서, 아래 숫자는 조종기 기본값보다 순하게 맞춰져 있습니다. 롤, 피치, 요는 손을 떼면 돌아오고, 스로틀은 조종기처럼 놓은 자리에 머뭅니다.",
"iulg1q": "키는 스틱이 아닙니다. 누르고 있으면 스틱이 34퍼센트까지 올라가 약 0.75초까지 거기에 머물다가 1.25초에 끝까지 늘어납니다. 그래서 아래 레이트는 조종기로 비행할 때의 레이트이고, 톡 치면 그 3분의 1쯤에만 닿습니다. 키보드 비행이 숫자보다 단단하고 느리게 반응하는 이유입니다. 게임패드나 USB 조이스틱 모드의 조종기는 곡선 전체를 씁니다. 그리고 키 레이스는 앵글로 시작하는데, 앵글은 이 곡선을 무시합니다. 쿼드의 키보드 레이스나 비행 중 M으로 아크로가 됩니다.",
"j83vdk": "조종기 신호를 기다리는 중입니다. 스틱을 움직여 보세요.",
"pc5ckr": "조종기가 1초에 {0}번 갱신하고 있습니다. 어느 쪽이든 Betaflight는 고정된 250 Hz 프레임으로 비행하므로, 이 값은 각 프레임의 값이 얼마나 새로운지를 뜻합니다.",
"tn3t15": "이것은 프레임 속도와 같은 초당 {0}번이며, 이 브라우저가 그리는 프레임마다 조종기를 한 번만 읽는다는 뜻입니다. 피드포워드는 프레임 사이의 변화에 작용하므로, 프레임마다 한 단계씩 움직이는 스틱은 미는 힘이 아니라 톡톡 치는 느낌의 연속이 됩니다. 아래 레이트로는 고칠 수 없습니다.",
"1iahfwq": "이 조종기는 스틱 전체 범위를 약 {0}단계로 보고하며, 높은 레이트에서는 느껴질 만큼 거칩니다. USB 보고가 더 촘촘한 조종기를 쓰거나 레이트를 낮추면 부드러워집니다.",
