"1idviqd": "더 높이. 트릭 전에 더 올라가세요.",
"zq4fgo": "깔끔하게: 부드러운 한 바퀴.",
"1a7n153": "그것은 {0}였습니다. 레슨이 원하는 것은 {1}입니다.",
"7uesfl": "그게 아닙니다. 목표를 다시 읽어 보세요.",
"1ikowyg": "더 높이. 시작하기 전에 더 올라가세요.",
"1qgbgyr": "반 바퀴 사이에 멈추세요: \"하나\"를 세고 진행.",
"181mx3x": "롤 반 바퀴, 멈춤, 그리고 롤 반 바퀴로 돌아오기.",
"wk4p7r": "같은 방향으로 반 바퀴 두 번, 사이에 멈춤.",
"wxj9rp": "다른 갭입니다. 다음은 {0}.",
"gitevc": "방금은 너무 빨랐습니다: {0} km/h. 더 일찍 브레이크를 걸고 돌아와 다시 하세요.",
"1jkvtjf": "방금은 너무 느렸습니다: {0} km/h. 속도를 더 실어 다시 하세요.",
"1rhk4hg": "고스트보다 {0}초 뒤. 더 세게가 아니라 더 부드럽게.",
"b1ky93": "랩 사이가 {0}초 차이 납니다. 매 랩 같은 라인으로 비행하세요.",
