"cyw1pe": "브라우저 FPV 레이싱 시뮬레이터. 컨트롤러는 Betaflight입니다. 트랙 언어는 Track Draw에서 왔습니다. 나머지는 한 명의 파일럿과, 느낌이 맞을 때까지 비행해 준 사람들입니다.",
"1sncokl": "제작",
"kai17": "이 시뮬레이터, 빌더, 공개 보드를 만들었습니다. 그 과정에서 Grok과 Claude 무리를 지휘했습니다.",
