"1m26mn1": "xAI의 Grok. 많은 줄, 많은 논쟁, 그리고 비행 감각에 대한 많은 고집.",
"1i8y2kj": "Anthropic의 Claude. 무리의 나머지 절반. 스틱을 잡은 사람은 같습니다.",
"sskqzq": "Betaflight, Track Draw, Grok, Claude, Dutch Drone Squad와 그 마크는 각 소유자의 것입니다. 채널 사진은 파일럿들의 것입니다. 여기서의 사용은 크레딧이며, 이 페이지를 보증한다는 주장이 아닙니다. 파트너의 마크는 파트너의 것이며 동의하에 표시합니다. WebFPV는 자유 소프트웨어이며 라이선스는",
