"1l302t4": "설정:",
"1ra2hmr": "쿼드를 맞혀 체력을 깎으세요. 바닥나면 색종이와 함께 터집니다. 한 번 터뜨릴 때마다 1점. 상자가 빨개지면 미사일이 쿼드를 따라갑니다.",
"abeo2g": "파이트!",
"43eacj": "모든 쿼드가 리본을 끌고 다닙니다. 다른 사람의 리본을 통과해 자르세요. 내 리본은 멀리 두세요. 짧게 잘리면 리본도, 그 파일럿도 사라집니다. 마지막까지 리본이 남은 사람이 승리.",
"1tj1cwp": "비행!",
"11xt3fz": "염소 뒤에서 낮게 비행하면 당신에게서 도망칩니다. Heads의 차고로 밀어 넣으세요. 염소는 마지막으로 밀어 넣은 사람의 것이니, 문 앞에서 가로채세요.",
