"l55p9d": "저장된 캘리브레이션이 이 패드에 없는 축에서 {0}을(를) 읽고 있어서 {1}은(는) 아무것도 읽지 못합니다. 이 패드에는 {2}이(가) 있습니다. 스틱 캘리브레이션이 실제로 보내는 값으로 다시 매핑합니다.",
"10cte0": "축 {0}이(가) 스틱처럼 움직이는데 시뮬레이터에서 읽는 것이 없습니다. 브라우저는 스틱을 받고 있고, 시뮬레이터는 잘못된 채널에 두고 있습니다. 스틱 캘리브레이션으로 1분 정도면 고칩니다.",
"13f86ul": "축 {0}이(가) 움직이는데 시뮬레이터에서 읽는 것이 없습니다. 그것이 작동하지 않는 스틱이라면 스틱 캘리브레이션이 올바른 채널에 넣어 줍니다.",
"3hxjne": "그것은 {0}이고, 축 {1}에 있으며, 시뮬레이터에 도달하고 있습니다.",
"4pid3q": "{0}이(가) 스틱처럼 움직였는데 시뮬레이터에서 {1}을(를) 읽는 것이 없습니다. 스틱이 잘못된 채널에 있는 것이며, 스틱 캘리브레이션으로 고칩니다.",
"13inlwb": "작동하지 않는 스틱을 양쪽 끝까지 움직이면서 막대를 보세요.",
"2niqw0": "조종기에서: 이 페이지를 열기 전에, 연결할 때 USB 조이스틱 모드를 고르고 선택된 모델을 확인하세요. 각 채널이 무엇을 보내는지는 모델이 정하며, 새 모델이나 빈 모델은 스틱에서 아무것도 보내지 않을 수 있습니다.",
"jem3gg": "조종기가 {0}축으로 들어오고 있습니다.",
"rr1z7d": "막대가 움직이지 않을 때: Windows",
"1j91r00": "Windows가 스틱을 인식하는지 확인하세요: Windows 키와 R을 누르고, joy.cpl을 입력한 뒤 Enter를 누르고, 조종기를 골라 속성을 열고 움직여 보세요. 거기서는 움직이는데 여기서는 안 움직이면, 이 화면에서 버그를 신고하고 그렇게 알려 주세요.",
"1qj9g8y": "거기서도 움직이지 않으면 조종기가 보내지 않는 것입니다. 그 Windows 창에서 보정해도 브라우저가 읽는 값은 바뀌지 않으니 할 필요가 없습니다.",
"1elsn67": "막대가 움직이지 않을 때: Mac",
"193sfmd": "macOS에는 자체 스틱 테스트가 없으므로 이 막대가 테스트입니다. 스틱이 한 브라우저에서는 움직이고 다른 브라우저에서는 안 움직이면, 이 화면에서 버그를 신고하고 어느 쪽인지 알려 주세요.",
"1lg87ci": "막대가 움직이지 않을 때: Linux",
"fk484m": "jstest-gtk나 evtest로 조종기가 무엇을 보내는지 볼 수 있습니다. 스틱이 거기서는 움직이는데 여기서는 안 움직이면, 이 화면에서 버그를 신고하고 그렇게 알려 주세요.",
