"nagz31": "보드가 그 평가를 받지 못했습니다.",
"9s1w1d": "별 하나에서 다섯 개까지, 한 사람당 평가 하나입니다. 바꾸거나 취소할 수 있습니다. 파일럿들은 이름 옆에서 평균을 보고, 보드는 가장 좋은 것을 먼저 놓을 수 있습니다.",
