"oi32d0": "튠 불러오기",
"1wgb6n": "k7mq-2xrt-9vwd 같은 공유 코드를 붙여 넣으세요. 무엇이든 바뀌기 전에 튠의 내용을 볼 수 있고, 내 것으로 되돌릴 수도 있습니다.",
