"4r9rjz": "후프 전용: 흰색 상자에 착륙",
"1dzhe8f": "출발 게이트 통과",
"n816s8": "출발 패드가 없어서 파일럿은 부지 왼쪽 가장자리에서 {0} m 안쪽, 위아래 중간에서 오른쪽을 보고 시작합니다.",
"1t711z2": "부지를 클릭해 놓으세요.",
"ekduh5": "포인터 아래에 있는 것 위에 놓입니다: 땅, 지붕, 컨테이너.",
"8o0928": "도구가 손에 남아 있어서 한 번 더 클릭하면 하나 더 놓입니다.",
"1329ksr": "땅을 클릭해 도로의 첫 노드를 놓으세요.",
"aaokh9": "차가 달릴 수 있는 모양으로 노드를 따라 휘어집니다.",
"1cziowk": "Powered by",
"1kjx060": ". 실제 필드 스케일, 실제 장애물, 크루에게 건넬 수 있는 도면.",
"ws88kv": "· 트랙 {0}",
"ojeg79": "· 트랙 {0}, 트랙 {1}",
"1rqldy2": ". andAgainFPV가 이 시뮬레이터로 가져왔습니다.",
"5k80a7": "챕터 {0}: 첫 비행, 타임 트라이얼",
"1r5bgka": "키보드 레이스는 앵글로 비행합니다. 스틱은 기울기. 손을 떼면 수평이 됩니다.",
"151jezz": "기둥 둘레를 한 바퀴 이상, 배를 위로 하고 비행.",
"2h13ul": "5인치 트랙",
"1ov5lw1": "{0}인치 트랙",
"tda83r": "5인치",
"1sss0ee": "챕터 {0}: 첫 비행, 탑승",
"yajn08": "{0}인치 트랙",
"1e05oqz": "빈 필드에서 빌더를 엽니다. 캔버스에 있던 것은 불러오기 목록에 남습니다. 만든 트랙은 이 브라우저에 저장됩니다. 데이터를 지우거나 다른 기기를 쓰면 처음부터 시작합니다. 트랙을 게시하면 공개 보드에 올라갑니다.",
"1cdhqo": "Betaflight 기본값",
"1dudsha": "WebFPV 제작",
"cuy5ed": "어느 한 부분이라도 바꾸면 다른 보드가 됩니다.",
"1iryycr": "Betaflight 자체 튠을 살짝 손본 것: 스틱에 조금 더 빨리 반응하고, 멈춘 뒤 되튐이 적습니다. 튠을 엽니다. 거기서 튠을 고르고 Betaflight 자체 슬라이더로 조정합니다. 내 레이트는 유지됩니다.",
"k6akiz": "프리스타일 맵",
"10ufhmj": "{0}인치",
"1r6qcm": "약하게",
"3sm2ze": "강하게",
"1xnvdto": "풀 사이즈 프리스타일 겸 레이스 쿼드: 출력에 비해 가볍고, 아주 빠르며, 그것을 쓸 만큼 넓은 필드. 기체마다 튠, PID, 배터리, 무게, 카메라를 따로 유지합니다. 기체를 바꾸면 그 기체의 설정이 두었던 그대로 돌아오고 (처음에는 기본 설정), 빌더도 야외 필드와 거실 사이에서 바뀝니다. 내 레이트는 기본값 그대로가 아니라면 함께 따라갑니다.",
"53x6f3": "보드나 다른 파일럿의 공유 코드를 붙여 넣으세요. 먼저 내용을 볼 수 있고, 내 것으로 되돌릴 수도 있습니다.",
"9ww08a": "마스터 배율",
"1vv9xkm": "추종, P와 I",
"fetog5": "드리프트와 흔들림, I",
"kyk48v": "댐핑, D",
"1roremq": "다이내믹 댐핑, D max",
"1e0pboe": "스틱 반응, FF",
"we45r2": "피치 추종",
"1dlny13": "피치 댐핑",
"1b1bac5": "아래의 모든 것은 이 튠의 것이며, 튠마다 조정값을 따로 유지합니다.",
"193v7i": "모두 한꺼번에: P, I, D와 피드포워드가 비율을 유지한 채 함께 변합니다. 이것이 \"더 단단하게\" 손잡이이며, 비행 감각 피드백에서 요청한 것입니다. 기본값은 {0}이고, 예전에 여기 있던 단단한 프리셋은 {1}이었는데, 그 피드백이 원한 정도가 대략 그만큼입니다.",
"c3fbrt": "스틱이 요구하는 레이트를 쿼드가 얼마나 세게 따라가는지. 낮으면 느긋하고 부드럽고, 높으면 목표값에 딱 붙어 유지합니다.",
"amoq3u": "느린 오차 항만 따로. 너무 낮으면 큰 동작에서 자세가 흘러가고, 너무 높으면 긴 스틱 조작 동안 쌓였다가 스틱이 중앙에 올 때 움찔하며 쏟아냅니다. 이 기체 모델에서는 흘러가기 훨씬 전에 움찔거림이 옵니다.",
"1kt9nne": "회전에 저항하고, 멈춤을 부드럽게 하고, 프롭워시를 가라앉힙니다. 실제 쿼드에서 D의 대가는 모터 열과 자이로 노이즈입니다. 이 모델의 자이로는 깨끗해서 댐핑이 거의 공짜이고, 단단한 튠은 이를 높게 씁니다.",
"1wqluz6": "빠른 움직임과 멈춤에서 기본 D 위에 D가 얼마나 더 얹히는지. 0이면 D가 일정합니다.",
"10nibr2": "피드포워드는 오차가 생기기 전에 스틱 움직임 자체를 밀어 줍니다. 높으면 즉각적이고, 너무 높으면 모든 동작의 시작에서 지나칩니다. 0이면 P와 D만으로 비행합니다.",
"i42c2o": "롤 대비 피치의 P와 I. 쿼드는 폭보다 길이가 길어서 보통 피치가 몇 퍼센트 더 큽니다.",
"1a9uio": "롤 대비 피치의 D. 피치 추종이 있는 것과 같은 이유입니다.",
"1eviq1n": "기반: Betaflight 기본값",
"eq2omx": "레이트: Actual {0}/{1}/{2}",
"9nmf95": "센터 감도",
"sdoqht": "최대 레이트",
