"15cdqf0": "도구",
"1btcvp2": "키를 누르거나 도구를 클릭한 다음 {0} 위를 클릭하세요. 도구는 선택된 채로 있어서, 게이트 열 개는 클릭 열 번입니다. Escape나 우클릭으로 내려놓습니다.",
"13j46d9": "키를 누르거나 도구를 클릭한 다음 {0} 위를 클릭하세요. 게이트는 선택된 채로 있어서, 게이트 열 개는 클릭 열 번입니다. 월, 허들, 업 게이트는 한 번에 하나씩입니다. Escape나 우클릭으로 내려놓습니다.",
"10m93q": "도로와 차량",
"1s59m59": "게이트와 마커",
"raiuna": "키를 누르거나 도구를 클릭한 다음 부지를 클릭하세요. 조각은 포인터 아래에 있는 것 위에 섭니다: 지면, 지붕, 컨테이너. 도구는 선택된 채로 있습니다. 빌딩, 컨테이너, 스케이트 세트는 동서남북에 맞춰 서고, 나머지는 자유롭게 돌릴 수 있습니다. Escape나 우클릭으로 내려놓습니다.",
