"317ur": "드래그하면 함께 옮깁니다. Delete로 제거합니다. 치수를 편집하려면 하나를 선택하세요.",
"1hc6e0r": "큐브는 한 조각으로, 파이프를 함께 쓰는 게이트 다섯 개입니다. 한 면으로 들어가 다른 면으로 나옵니다: 어느 면인지는 비행 순서 도구로 바꿉니다.",
