"duccyy": "기울기(도)",
"1qy8eue": "기울기",
"1l115jq": "기울기 0은 수직 게이트입니다. 기울기 90은 개구를 평평하게 눕혀서, 곧장 아래나 위로 통과합니다. 그 사이는 모두 기울어진 다이브 게이트입니다.",
"s3robe": "지름",
"1tlglvi": "꼭짓점 사이 폭",
"yq4hld": "글자로 만들기",
"6vxj0r": "이 게이트는 지금 서 있는 자리와 방향 그대로, 비행 순서의 같은 자리에서 파이프로 된 대문자가 됩니다. 통과가 지나는 틈이 글자 크기의 기준이 됩니다.",
