"1acjmu8": "물리가 돌린 상자를 다룰 수 있을 때까지, 동서남북에 맞춰 4분의 1 바퀴씩만 돕니다.",
"nf3vcm": "스타일",
"jw2n94": "지면 아래로 {0} m 묻혀 있습니다. 지면 아래에 있는 것은 그려지지 않고 단단하지도 않습니다. 바닥 높이를 음수로 하면 조각을 반쯤 숨길 수 있습니다.",
