"14kd816": "노드 삭제",
"7fk9fq": "단축키: Delete",
"psho8c": "노드를 드래그하면 도로 모양을 바꾸고, 도로 자체를 드래그하면 옮깁니다. 두 노드 사이의 +를 드래그하면 그곳에 노드를 추가합니다. 노드를 클릭하고 Delete를 누르면 뺍니다.",
