"1p68bad": "다른 색으로 칠하기",
"1gzljgt": "포워드는 첫 노드에서 {0}을(를) 따라 출발하고, 리버스는 첫 노드 쪽으로 돌아갑니다. 어느 쪽이든 양 끝에서 돌아섭니다.",
"orucb5": "포워드는 도로를 깐 순서대로 왼쪽 차로를 달리고, 리버스는 반대 차로를 반대 방향으로 달립니다.",
