"1kt144f": "차를 드래그하면 도로를 따라 밀립니다. 2차로 루프의 오른쪽 절반에 놓은 차는 반대 차로를 달립니다.",
"1e9l9b2": "갭 이름",
"1b5hejq": "포인트",
"1s8mpdp": "윈도",
"1xuswhn": "진행 방향 기준 폭 {0} m, 바닥 높이에서 {1} m 위, 지면에서 {2} m 떨어진 윈도. 단단하지 않고 월드에 그려지지도 않습니다: 파일럿은 통과하면서 찾아냅니다.",
"1n1avl0": "비행 방법",
"17kqvbs": "각 구멍이 독립된 게이트입니다. 동작을 고른 다음 그 라인을 비행하세요. 레이스 라인이 돌아가는 길을 보여 줍니다.",
"101yslu": "도는 방향",
"z90btw": "이 조합은 이름 있는 동작이 아닙니다. 나열한 구멍은 여전히 각각 독립된 게이트로 칩니다.",
