"df9dnw": "들어가며",
"1h51c6r": "깃발을 도는 턴: 둘레를 돌아서 지나가고 위로는 넘지 않습니다",
"1drm4l8": "이 통과 뒤에 라인이 하는 것",
"z3khip": "이 통과 전에, 들어오면서 라인이 하는 것",
