"v2b64n": "이 통과 앞에 놓인 것이 없습니다: 라인은 앞 조각에서 들어옵니다.",
"jhv2pt": "{0}(이)라고도 합니다.",
"1ora819": "라인은 깃발을 지나 계속 갑니다: 돌지 않습니다.",
"140sy7r": "{0} 턴 여유 간격을 두고 깃발을 돌기 때문에, 둘레를 돌아서 지나가고 위로는 넘지 않습니다.",
"lrap3c": "이 게이트 돌기",
"puy9pc": "{0} 깃발 돌기",
"1skujz": "통과한 뒤, 깃발 쪽 다리를 수평으로 180도 돌기",
