"8grjfz": "돌면서 올라가기",
"19f8jhg": "끝까지 같은 높이로",
"193mu7r": "라인이 어떻게 도는지",
"1d5l3kp": "어느 로고",
"fuh6y1": "{0}, 위의 {1} x {2} m 영역 안에 맞춰 넣었습니다. 영역 크기를 로고 모양에 맞추면 더 많이 채웁니다.",
"u7r6mk": "개구 크기",
"x8sjyl": "이 게이트들은 크기가 모두 같지 않습니다. 하나를 고르면 전부 그 크기로 설정됩니다.",
"1hzx9ty": "직접 정한 크기. 프리셋을 골라 표준 크기로 돌아가거나, 아래에 개구를 입력하세요.",
"z7pdd0": "단 간격",
"120dj14": "{0}은(는) 한 개구에서 다음 개구까지 올라가는 높이로, 아래 변에서 아래 변까지입니다. 두 개구는 프레임 파이프 하나를 함께 쓰므로, 자연스러운 간격은 개구 높이에 파이프를 더한 값이며, 프리셋이 이 값을 설정합니다.",
"vgll2t": "둥근 개구 하나, 지름 {0}{1}",
"15487wm": "육각 개구 하나, 꼭짓점 사이 {0}{1}, 변 사이 {2}{3}",
"1v2qxxn": "개구 {0}개, 각각 크기가 다름. {1}.",
"6sk7cs": "{1} x {2}{3} 개구 {0}개. {4}.",
"1hbf8r7": "{0}, 중심은 {3}에서 {1}{2} 위.",
"zoltl8": "{0} 구조물 꼭대기 {1}{2}.",
"1cy6t48": "각 개구",
"4ikah4": "스택의 모든 개구는 독립된 게이트입니다: 각각 폭과 높이를 따로 줄 수 있고, 레이스는 각 통과를 그 개구의 크기로 판정합니다. 건드리지 않은 개구는 위의 스택 크기를 따릅니다.",
"sfqavh": "개구 {0} 폭",
"lmcl0k": "개구 {0} 높이",
"1gbmevb": "개구 {0}을(를) 스택 크기로 되돌리기",
"nfe36u": "어느 글자인지",
"1m3kezv": "{0} 각 틈은 비행 순서에서 독립된 게이트입니다: 통과마다 어느 틈을 지나는지 정해집니다.",
"1ugsv61": "글자 폭",
"1s7eddk": "글자 높이",
"vq42m7": "{0}. 파이프는 2인치이며, 글자의 파이프는 단단합니다.",
"18ku1py": "게이트로 만들기",
"h5sgwm": "주 틈이 있는 자리에 같은 크기의 일반 게이트를 둡니다. 다른 틈을 지나는 통과는 순서에서 빠집니다.",
"q7q9fq": "프레임",
"r64mng": "파이프가 사라집니다: 틈은 계속 판정되고 빛나며, 부딪힐 것이 없습니다. 방에서는 틈만 보입니다.",
"s9vozj": "이 글자는 파이프로 만들어졌습니다. 보이지 않게 하면 주변에 아무것도 세우지 않은 목표로 틈만 남습니다.",
"1rkao2q": "파이프 되돌리기",
"1ezapez": "보이지 않게 하기",
"1h88uzq": "각 변은 별개의 파이프입니다: 위 바는 맨 위 개구 위에, 아래 바는 맨 아래 개구 아래에 있고, 기둥은 개구마다 한 구간입니다. 왼쪽과 오른쪽 버튼은 기둥 전체를 빼고, 그 아래 버튼은 개구 하나의 구간을 뺍니다. 하나를 빼도 개구는 계속 판정됩니다. 3D 보기에서 선택한 게이트의 파이프를 클릭하고 Delete를 누르면, 클릭한 구간만 빠집니다. 왼쪽과 오른쪽은 윗변 깃발처럼 게이트를 마주 보고 본 방향입니다.",
"3wzvo0": "각 변은 별개의 파이프입니다. 하나를 빼도 개구는 계속 판정되고 빛나며, 그 자리에 부딪힐 파이프가 없습니다. 3D 보기에서 선택한 게이트의 파이프를 클릭하고 Delete를 누르세요. 왼쪽과 오른쪽은 윗변 깃발처럼 게이트를 마주 보고 본 방향입니다.",
"1vhm01f": "{0} 빼기",
"80wioy": "{0} 되돌리기",
"a9ak0k": "{0} 구간 빼기",
"1mtqtr1": "{0} 구간 되돌리기",
"1302s3v": "프레임 되돌리기",
"ka4wbv": "모든 변 되돌리기",
"103wg51": "모든 변을 빼고, 깃발이 있으면 깃발도 뺍니다: 개구는 계속 판정되고 빛나며, 부딪힐 것이 없습니다.",
"e2847m": "윗변 깃발",
"127gict": "허들에서 페넌트가 서는 자리: 양 끝입니다. 마스트 높이는 아래 치수의 깃발 높이이며, 마스트는 단단합니다.",
"17wx66j": "게이트를 마주 보았을 때 윗변에서 페넌트가 서는 자리. 위에 두면 판 한가운데, 개구 바로 위에 마스트 하나가 섭니다. 마스트 높이는 아래 치수의 깃발 높이이며, 마스트는 단단합니다: 위쪽 레일로 다이브하는 파일럿이 부딪힐 수 있습니다.",
"d0y2y3": "구멍",
"1w31kfz": "초록 사각형이 통과해야 하는 공간입니다. 도면의 둥근 핸들을 드래그하면 마커 둘레 어디로든, 한 바퀴 끝까지 돌릴 수 있습니다. 쪽 뒤집기는 반대쪽으로 보내고, 다시 계산은 자동 규칙, 즉 턴의 바깥쪽으로 돌려보냅니다.",
"1wg2ncb": "면 뒤집기",
"172xku9": "쪽 뒤집기",
"3d7qa3": "단축키: X",
"1tdvisw": "다시 계산",
"qqpglk": "자동 규칙에 다시 맡깁니다. 이전 요소에서 다음 요소로 가는 라인을 따라 향하게 합니다.",
"1c086it": "선택된 것이 없습니다. 요소를 클릭해 편집하거나, 빈 지면에서 상자를 드래그해 여러 개를 선택하세요.",
"3eggiu": ": RaceGOW, 방에서 날리는 65 mm 후프용. 게이트는 24에서 28인치, 인접한 게이트는 중심 간격 30인치, 트랙 전체는 가장 작은 게이트에서 4 x 6피트 안에 들어가며 게이트와 함께 커집니다. 모든 조각은 방 한가운데에서 인치로 재고, 그리드는 1인치입니다.",
"1329h41": ": 필드에서 날리는 5인치 쿼드. MultiGP 게이트 크기이며, 모든 조각은 필드 모서리에서 미터로 잽니다.",
