"186guzs": "스플라인 접선의 길이로, 다음 매듭까지 간격에 대한 비율입니다. 약 3분의 1이면 직각을 지나는 원호가 그려집니다. 높이면 라인이 넓게 부풀고, 낮추면 코너가 각집니다.",
