"zafenl": "한 조각: 파이프를 함께 쓰는 게이트들입니다. 한 면으로 들어가 다른 면으로 나오며, 비행 순서 도구로 어느 면인지 바꿉니다. 드래그해 옮기세요. Q와 E로 돌립니다. 화살표 키로 조금씩 밉니다.",
