"1czqdml": "하나의 게이트로 합칩니다: 어느 개구를 지나든 한 번으로 치고, 먼저 비행한 쪽의 자리에 들어갑니다. 먼저 둘 다 보이지 않게 하면 아무것도 세우지 않은 L자나 T자 모양의 목표가 됩니다.",
