"1fgg8vv": "{0}이(가) {1}의 반대쪽을 향합니다. 라인이 거꾸로 나갑니다. X를 눌러 면을 뒤집으세요.",
"19psiq7": "{0}이(가) {1} 쪽으로 되돌아 향합니다. 라인이 거꾸로 들어옵니다. X를 눌러 면을 뒤집으세요.",
"1xkwf83": "랩이 {0}에서 멀어지는 방향으로 출발합니다. 출발 패드를 돌리거나 트랙 순서를 바꾸세요.",
"1vv4mnm": "랩이 {1} 다음에 {0}의 앞쪽에서 돌아옵니다. 그 면을 뒤집거나 마지막 요소를 그 뒤로 옮기세요.",
"1gf0z7v": "레이스 속도의 쿼드는 그렇게 비행하지 못합니다. 트랙에서 의도한 것이라면 필드 설정의 \"이 반경 미만이면 경고\"를 낮추세요.",
