"1l1fncv": "{0}이(가) {1}의 반대쪽을 향한 채 끝나서, 라인이 거기에 닿으려면 되돌아야 합니다. 동작이 끝나는 곳에 {2}을(를) 두거나 동작을 반대로 돌리세요.",
"1ozh84i": "{0}에서 거꾸로 나와 {1}(으)로 들어가므로, 라인이 그것을 시작하려면 되돌아야 합니다. {2}을(를) 반대로 돌리거나 동작을 옮기세요.",
"1emgxmg": "{0}이(가) {1} 쪽으로 되돌아가는 방향으로 시작해서, 라인이 그것을 시작하려면 되돌아야 합니다. 동작이 시작하는 곳에 {2}을(를) 두거나 동작을 반대로 돌리세요.",
"laqehz": "라인이 랩의 {1} m 지점에서 {0} 위로 넘어갑니다. 깃발의 선은 위로 끝없이 이어지므로, 돌아서 지나가고 위로는 넘지 않습니다: 라인을 깃발의 한쪽으로 옮기세요.",
"1xr491b": "{0}은(는) {2}에 대해 직각에서 {1}도 어긋나 있습니다. 모든 게이트는 트랙의 두 축 중 하나를 따라 향합니다: 그쪽과 직각이 되게 돌리세요.",
"1tgybl6": "{0}의 개구는 {1}입니다. RaceGOW 게이트는 28 in 정사각형 안에 들어갑니다.",
"1rlgckd": "{0}의 개구는 {1}입니다. RaceGOW의 최소 게이트는 24 in입니다.",
"6we35z": "{0}은(는) 맨 아래 개구의 중심이 {1}에 있습니다. 지면의 게이트는 중심이 20 in 이하입니다.",
"1d69zcl": "{0}의 두 번째 개구는 중심이 {1}에 있습니다. 2단 스택의 위 게이트는 최소 42 in 높이여야 합니다.",
"xv7gqv": "{0}의 세 번째 개구는 중심이 {1}에 있습니다. 세 번째 게이트는 최소 69 in 높이여야 합니다.",
"1imcxyb": "{0}은(는) {1}까지 올라가 {2} m 천장을 뚫습니다. RaceGOW 트랙은 실내에서 비행합니다.",
"19w4clv": "{0}은(는) 개구를 {1} 간격으로 쌓았습니다. 인접한 게이트는 쌓든 나란히 놓든 중심 간격이 27에서 33 in입니다.",
"1ims1cr": "{0}와(과) {1}은(는) {2} 떨어져 있습니다. 이렇게 가까운 두 게이트는 인접한 것이며, 인접한 게이트는 중심 간격이 27에서 33 in입니다.",
"8wy7kh": "{0}와(과) {1}은(는) {2} 떨어져 있습니다. 나란한 한 쌍으로 의도했다면, 인접한 게이트는 중심 간격이 27에서 33 in이고 기준은 30입니다.",
"107lerp": "{0}은(는) {2}에서 {1} 떨어져 있습니다. 폴은 게이트 중심에서 최소 14 in 떨어져야 합니다.",
"1uyg16": "{0}와(과) {1}은(는) {2} 떨어져 있습니다. 두 폴은 최소 36 in 떨어져야 합니다.",
"zolwjx": "트랙의 범위는 {0} x {1} m입니다. RaceGOW 트랙은 이 게이트 크기에서 {2} x {3} m 안에 들어갑니다.",
"4hr5zo": "S를 누르고 출발할 곳을 클릭하세요.",
"lk5z4a": "이 줄은 두 높이에 걸쳐 있기도 합니다: {0}번 매트는 {1} m에, 기체의 매트는 {2} m에 있어서, 매트가 {3} m에 그려지고 일부는 뜨거나 묻힙니다. 줄을 한 면 위로 옮기세요.",
"ls6ln3": "출발 패드가 두 높이에 걸쳐 있습니다: {0}번 매트는 {1} m에, 기체의 매트는 {2} m에 있습니다. 매트는 {3} m에 그려지므로 일부는 뜨거나 묻힙니다. 줄을 한 면 위로 옮기세요.",
"1hy0328": "{0}이(가) {1}와(과) 겹칩니다: 하나가 다른 하나를 뚫고 세워져 있습니다. 둘 중 하나를 옮기세요.",
"500wke": "{0}와(과) {1} 사이에 {2} m 틈이 남습니다. 5인치가 지나가려면 {3} m가 필요하니, 틈을 막거나 넓히세요.",
"10fprle": "{0}의 날개가 {1}을(를) 뚫고 돌게 됩니다. 둘 중 하나를 옮기거나 풍차를 돌리세요.",
"h9gzex": "{0}은(는) 날지 않습니다: 맵에서는 풍선 추격이 하나만 날며, 그것은 {1}입니다. 둘 중 하나를 제거하세요.",
"ym814r": "{0}의 윈도를 {1}이(가) 가로막고 있어, 깨끗하게 통과할 수 없습니다. 갭이나 그 안에 있는 것을 옮기세요.",
"1l0co51": "이름 붙은 갭",
"d008ky": "{0}이(가) 부지 밖에 서 있습니다.",
"g0m2mr": "{0}이(가) 부지 가장자리를 넘어갑니다.",
"np34nj": "{0}은(는) 지면 아래로 완전히 묻혀 있어, 보이는 부분도 단단한 부분도 없습니다. 바닥 높이를 올려 끌어올리세요.",
"2cz3wz": "이 맵에는 단단한 것이 {0}개 있어, 느린 컴퓨터에서도 부드럽게 불러오고 비행하도록 맵에 두는 한도 {1}개를 넘습니다. 가장 큰 것은 {2}: {3}.",
"1o9p6b3": "{0} 주변에서 물리는 기체와 대조할 도형이 {1}개인데 최대 {2}개만 확인합니다: 나머지는 빠지고, 그곳의 기체는 그것들을 뚫고 지나갈 수 있습니다. 이 요소들을 더 넓게 벌리거나 수를 줄이세요.",
"36jvfa": "{0}에 도로가 없습니다: {1}. 주차된 채로 있으며, 부지 남쪽 가장자리를 따라 난 줄에 그려집니다. 도로 위로 드래그하거나 삭제하세요.",
"58628i": "{0}이(가) 부지 가장자리를 넘어 이어집니다.",
"kof9h3": "{0}이(가) {1}을(를) 뚫고 지나갑니다: 그 위의 차가 들이받게 됩니다. 차가 지나갈 공간이 생길 때까지 도로나 {2}을(를) 옮기세요.",
"1x8yhyt": "{0}이(가) 출발 패드 위를 지나서, 그 위의 차가 출발을 기다리는 기체를 뚫고 지나갑니다. 도로나 패드를 옮기세요.",
"11r26o9": "{0}이(가) 기체가 출발하는 곳에서 1미터 안쪽을 지나서, 그 위의 차가 패드를 떠나기도 전의 기체를 스칩니다. 도로나 패드를 옮기세요.",
"e5birv": "{0}이(가) 출발 패드가 없을 때 파일럿이 출발하는 곳을 지나서, 그 위의 차가 기체를 뚫고 지나갑니다. 도로를 옮기거나, S를 눌러 출발 패드를 도로에서 떨어진 곳에 놓으세요.",
"5s8foe": "{0}와(과) {1}이(가) 모두 열린 도로인 {2} 위에 있습니다: 모든 차가 가운데로 달려 끝까지 갔다가 돌아오므로, 두 대가 정면으로 만나 서로를 뚫고 지나갑니다. 도로를 닫아 루프로 만들거나 차를 한 대만 두세요.",
"1c7ews2": "{0}와(과) {1}이(가) {2}의 한 차로를 서로 반대 방향으로 달려서, 정면으로 만나 서로를 뚫고 지나갑니다. 도로를 2차로로 하거나 둘 중 하나를 돌려세우세요.",
"b92v0l": "둘의 최고 속도와 드리프트를 같게 하거나, 하나를 리버스로 설정해 반대 차로를 달리게 하세요.",
"1t8095q": "둘의 최고 속도와 드리프트를 같게 하거나, 도로를 2차로로 하고 하나를 리버스로 설정하세요.",
"ntbmqa": "{0}이(가) {1}와(과) 겹친 채 출발합니다. 둘 중 하나를 도로를 따라 밀어 옮기세요.",
